"""Compare generated numerical tables to the original saved experiment results."""

from io import BytesIO
from pathlib import Path
import argparse
import json
import zipfile

import numpy as np
import pandas as pd
from battwin_framework.experiment import ASSETS


def compare(workspace, *, rtol=2e-5, atol=2e-4):
    root = Path(workspace).resolve() / "codex_work/results"
    checked, failures = [], []
    with zipfile.ZipFile(ASSETS / "reference_results.zip") as archive:
        for name in archive.namelist():
            # Provenance records and original input exports are not generated by
            # the scientific notebook itself. Compare its numerical CSV exports.
            if not name.endswith(".csv") or name.endswith("/input_data.csv"):
                continue
            path = root / name
            if not path.exists():
                failures.append({"table": name, "error": "missing output"})
                continue
            try:
                expected = pd.read_csv(BytesIO(archive.read(name)))
                actual = pd.read_csv(path)
                pd.testing.assert_frame_equal(actual, expected, check_dtype=False,
                    check_exact=False, rtol=rtol, atol=atol)
                checked.append(name)
            except Exception as error:
                failures.append({"table": name, "error": str(error)[:1600]})
    return {"tables_passed": len(checked), "tables_failed": len(failures),
            "rtol": rtol, "atol": atol, "failures": failures}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("workspace")
    parser.add_argument("--report")
    args = parser.parse_args()
    result = compare(args.workspace)
    if args.report:
        Path(args.report).write_text(json.dumps(result, indent=2), encoding="utf-8")
    print(json.dumps(result, indent=2))
    raise SystemExit(bool(result["tables_failed"]))
